```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {}", now.seconds);
        let accepted = notifier::notify(&message);

        // `ensures notified == true` must hold of every output, so a refused
        // notification must not produce a report. With panic = "abort" this
        // becomes a trap, and no output is emitted.
        if !accepted {
            panic!("notifier did not accept the heartbeat; refusing to report notified = true");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified: true,
        }
    }
}

export!(Node);
```

